    /** The icon for a name or a v4 glyphicon name, or null. */
    public static function resolve(string $name): ?string
    {
        $name = strtolower(trim((string) preg_replace('/^glyphicon\s+/', '', trim($name))));
        $name = (string) preg_replace('/^glyphicon-/', '', $name);
        if (isset(self::ICONS[$name])) {
            return $name;
        }
        return self::GLYPHICONS[$name] ?? null;
    }

    /** An inline, decorative SVG icon ('' for unknown names). */
    public static function svg(string $name, string $class = ''): string
    {
        $icon = self::resolve($name);
        if ($icon === null) {
            return '';
        }
        return '<svg class="cal5-icon' . ($class !== '' ? ' ' . $class : '') . '" viewBox="0 0 24 24" aria-hidden="true" focusable="false">'
            . self::ICONS[$icon] . '</svg>';
    }

    /** The icon as an SVG data URI (black strokes), for CSS masks; null for unknown names. */
    public static function dataUri(string $name): ?string
    {
        $icon = self::resolve($name);
        if ($icon === null) {
            return null;
        }
        $svg = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' "
            . "stroke-linecap='round' stroke-linejoin='round'>" . str_replace('"', "'", self::ICONS[$icon]) . '</svg>';
        return 'data:image/svg+xml,' . strtr(rawurlencode($svg), ['%20' => ' ', '%27' => "'", '%3D' => '=', '%3A' => ':', '%2F' => '/', '%2C' => ',']);
    }

    /** @return list<string> */
    public static function names(): array
    {
        return array_keys(self::ICONS);
    }
}
